// 'use client'  <-- at the top of the file in Next.js
function App() {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Big mostly-static marketing page…</h2>
      <button onClick={() => setOpen(o => !o)}>{open ? 'Hide' : 'Show'} FAQ</button>
      {open && <p>The whole page is now a Client Component.</p>}
    </div>
  );
}

solution.code:
// Page stays a Server Component (static); only FaqToggle is a Client Component.
function FaqToggle() { // 'use client' in its own file
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(o => !o)}>{open ? 'Hide' : 'Show'} FAQ</button>
      {open && <p>Only this widget ships JS.</p>}
    </>
  );
}
function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Big mostly-static marketing page…</h2>
      <FaqToggle />
    </div>
  );
}

